import json,pathlib
p=pathlib.Path('/tmp/harso-sk/proto/lanes/mac-settings');a=json.loads((p/'frames.json').read_text());expected=json.loads((p/'inventory.json').read_text())
assert len(a)==28 and len({(r['page'],r['id']) for r in a})==28
for app in ['Proto macOS Light','Proto macOS Dark']:assert set(r['id'] for r in a if r['page']==app)==set(expected)
lines=['# mac-settings prototype lane','', 'Built 28 macOS frames: Settings + 11 category screens + 2 overlays in Light/Clean and Dark/Clean. Frames are 1440×900, flow group 2 at y=2120, x increment 1560; captions at y=2092. Document not saved.','', '## Frames','', '| Page | Screen id | Frame id |','|---|---|---|']
for r in sorted(a,key=lambda r:(r['page'],r['x'])):lines.append('| '+r['page']+' | '+r['id']+' | `'+r['frame']+'` |')
lines+=['','## Navigation names','',', '.join('`'+v+'`' for v in sorted({v for r in a for v in r['links']})), '', 'Every category row targets its explicit settings-<category> screen. Account is included as settings-account as requested by the 11-category inventory. Sign-out Cancel → link:back; confirmation → link:signin. Plan Cancel → link:back; plan choices → link:settings-billing. Global sidebar links are emitted by the shared shell helper.', '', 'Non-navigation local actions (switches, selects, permissions, external-link fixtures) are named to their owning screen as prototype self-links; this lane does not simulate backend mutations or external services. Parent lane wires all navigation flows.', '', '## Verification','', '- Read-back inventory validates all 28 unique frames, exact dimensions and row placement.', '- Descendant bounds audit returns zero overflows on every screen (symbol internals excluded). Fixed inherited sidebar footer spacing locally from 10px to 6px; shared shell source untouched.','- All 28 frames exported with Sketch MCP screenshots, then checked in appearance-specific contact sheets.','- Account screenshot separately checked at 1440×900 against the real settings reference.','- Existing kit symbols reused for Switch, Kbd, and AgentLimitsCard; shared tokens and macOS sidebar/main shell used throughout.','- Both dialogs draw the underlying Settings/Billing screen with a 40% ink scrim.','', '## Files and caveats','', '- Generators: one settings*.js per screen, parameterized by APP; run-*.js capture each appearance.','- common.js, build.py, verify.py, audit.js, frames.json, inventory.json, build.log, audit.log, report.py and contact-*.png reside in this lane directory.','- Individual screenshots: /tmp/harso-sk/shots/mac-settings-{Light,Dark}-<id>.png.','- About version is explicitly labeled illustrative prototype copy; not a claimed production version.','- Only this lane’s frames/captions were created; no kit pages or other lane screens changed.','', 'LANE_RESULT: mac-settings complete — 28 frames, 2 appearances, named navigation, screenshot-verified; document unsaved.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n');print('REPORT_WRITTEN',len(a))
